export const QUIZ_ITEMS = [
  { id: "1865", section: "العلماء والأئمة", category: "العلماء", level: "متوسط", question: "من هو الإمام ابن تيمية؟ وما أبرز مؤلفاته؟", answer: "هو شيخ الإسلام أحمد بن عبد الحليم بن تيمية الحراني الحنبلي (661-728هـ). وُلد في حرّان وعاش في دمشق. أبرز مؤلفاته: «درء تعارض العقل والنقل»، «منهاج السنة النبوية»، «الفتاوى الكبرى»، «الاستقامة»، «اقتضاء الصراط المستقيم». اشتُهر بالتجديد في مسائل العقيدة والرد على الفلسفة الكلامية وعلى الغلو والبدع.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1866", section: "العلماء والأئمة", category: "العلماء", level: "صعب", question: "ما الفرق بين «الإسناد» و«المتن» في علم الحديث؟", answer: "الإسناد (السند): هو سلسلة الرواة الذين نقلوا الحديث من راوٍ إلى آخر حتى وصل إلى النبي ﷺ. والمتن: هو نص الحديث ومضمونه الذي قاله النبي ﷺ أو فعله. الحكم على الحديث صحةً وضعفاً يعتمد في الأساس على دراسة الإسناد (رجاله وعلله)، ثم دراسة المتن للكشف عن الشذوذ والنكارة.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1867", section: "العلماء والأئمة", category: "العلماء", level: "متوسط", question: "من هو الإمام النووي؟ وما أبرز مؤلفاته؟", answer: "هو الإمام يحيى بن شرف النووي الشافعي (631-676هـ)، من أكبر علماء الإسلام وأتقاهم. وُلد في نوى بسوريا. أبرز مؤلفاته: «رياض الصالحين» و«الأذكار» و«المنهاج في شرح صحيح مسلم» (المعروف بشرح النووي) و«المجموع شرح المهذب» و«الأربعون النووية». توفي وعمره 45 سنة لكنه ترك إرثاً علمياً ضخماً يُدرَّس حتى اليوم.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1868", section: "العلماء والأئمة", category: "العلماء", level: "صعب", question: "ما المذاهب الفقهية الأربعة المعتمدة؟ ومن مؤسسوها؟", answer: "المذاهب الفقهية الأربعة: 1) الحنفي — مؤسسه الإمام أبو حنيفة النعمان (80-150هـ). 2) المالكي — مؤسسه الإمام مالك بن أنس (93-179هـ). 3) الشافعي — مؤسسه الإمام محمد بن إدريس الشافعي (150-204هـ). 4) الحنبلي — مؤسسه الإمام أحمد بن حنبل (164-241هـ). كل مذهب له منهجه في الاجتهاد والاستدلال، ويُعبّر عن فهم دقيق للنصوص الشرعية، والخلاف بينها رحمة وتوسعة.", explanation: "يُستفاد منه في باب العلماء. يُستفاد منه في باب العلماء مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1869", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "سهل", question: "من هو الإمام البخاري وما اسمه الكامل؟", answer: "هو محمد بن إسماعيل البخاري (194-256هـ)، وُلد في بخارى بأوزبكستان. مؤلف أصح كتاب بعد كتاب الله وهو الجامع الصحيح المعروف بصحيح البخاري الذي يحتوي على 7563 حديثاً مكرراً، وهو إمام علماء الحديث.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1870", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "متوسط", question: "في أي قرن عاش الإمام الغزالي وما لقبه الشهير؟", answer: "عاش أبو حامد الغزالي (450-505هـ) في القرن الخامس الهجري. لقّبه العلماء بـ«حجة الإسلام» لعلمه الغزير ومواقفه الدفاعية عن الإسلام. وُلد في طوس بخراسان (إيران)، وأشهر كتبه إحياء علوم الدين.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1871", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "متوسط", question: "من هو ابن تيمية وأين وُلد وتوفي؟", answer: "هو أحمد بن عبد الحليم ابن تيمية الحراني (661-728هـ). وُلد في حران (جنوب تركيا) وتوفي في سجن دمشق. عالم حنبلي موسوعي في الفقه والعقيدة والتفسير. أشهر طلابه ابن قيم الجوزية، وأشهر كتبه الفتاوى الكبرى ومنهاج السنة.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1872", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "متوسط", question: "ما اسم الإمام الشافعي كاملاً وأين وُلد؟", answer: "هو محمد بن إدريس الشافعي القرشي (150-204هـ). وُلد في غزة (فلسطين) وتوفي في مصر. مؤسس المذهب الشافعي وصاحب كتاب الرسالة أول مصنَّف في أصول الفقه. حفظ القرآن في سن السابعة وحفظ الموطأ في سن العاشرة.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1873", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "صعب", question: "من هو ابن حجر العسقلاني وما أهم مؤلفاته في الحديث؟", answer: "هو أحمد بن علي بن حجر العسقلاني (773-852هـ)، مصري الأصل من عسقلان. أمير المؤمنين في الحديث. أشهر مؤلفاته: فتح الباري شرح صحيح البخاري (13 مجلداً)، والإصابة في تمييز الصحابة، وتقريب التهذيب. استغرق فتح الباري منه 25 عاماً.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1874", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "صعب", question: "ما مدينة الميلاد والوفاة لكلٍّ من الأئمة الأربعة؟", answer: "أبو حنيفة: وُلد في الكوفة وتوفي في بغداد. مالك بن أنس: وُلد وتوفي في المدينة المنورة. الشافعي: وُلد في غزة وتوفي في الفسطاط (القاهرة). أحمد بن حنبل: وُلد وتوفي في بغداد.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1875", section: "العلماء والأئمة", category: "العلماء والأئمة", level: "صعب", question: "من هو ابن قيم الجوزية وما علاقته بابن تيمية؟", answer: "هو محمد بن أبي بكر ابن قيّم الجوزية (691-751هـ)، من دمشق. لازم شيخه ابن تيمية نحو 17 عاماً وسجن معه في قلعة دمشق. أشهر كتبه: زاد المعاد، إغاثة اللهفان، مدارج السالكين. أتم كثيراً مما بدأه ابن تيمية.", explanation: "يُستفاد منه في باب العلماء والأئمة. يُستفاد منه في باب العلماء والأئمة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1876", section: "التجويد", category: "المخارج", level: "سهل", question: "ما مخارج الحروف الأساسية؟", answer: "خمسة مخارج عامة: الجوف (لحروف المد الثلاثة)، والحلق، واللسان، والشفتان، والخيشوم (مخرج الغنة). ويتفرع منها على المذهب المختار — وهو اختيار ابن الجزري — سبعة عشر مخرجًا خاصًّا", explanation: "يُستفاد منه في باب المخارج. يُستفاد منه في باب المخارج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1877", section: "التجويد", category: "المخارج", level: "متوسط", question: "من أي مخرج يخرج حرف الغين؟", answer: "من أدنى الحلق، أي أقربه إلى الفم، ومعه حرف الخاء. والحلق ثلاثة مخارج: أقصاه — وهو أبعده عن الفم — للهمزة والهاء، ووسطه للعين والحاء، وأدناه للغين والخاء", explanation: "يُستفاد منه في باب المخارج. يُستفاد منه في باب المخارج مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1878", section: "التجويد", category: "الأحكام", level: "سهل", question: "ما الإدغام في التجويد؟", answer: "إدخال حرف ساكن في حرف متحرك بعده بحيث يصيران حرفاً واحداً مشدداً من جنس الثاني. وحروفه عند النون الساكنة والتنوين ستة مجموعة في «يرملون»، وينقسم إلى إدغام بغنة في حروف «ينمو»، وإدغام بغير غنة في اللام والراء", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1879", section: "التجويد", category: "الأحكام", level: "متوسط", question: "ما الإخفاء في التجويد؟", answer: "النطق بالنون الساكنة أو التنوين بصفة بين الإظهار والإدغام، عارياً عن التشديد، مع بقاء الغنة مقدار حركتين. وحروفه خمسة عشر، وهي الباقية بعد حروف الإظهار الستة وحروف الإدغام الستة وحرف الإقلاب (الباء)", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1880", section: "التجويد", category: "الأحكام", level: "صعب", question: "ما المد المتصل؟", answer: "مدٌّ سببه همزة وقعت بعد حرف المد في الكلمة نفسها، نحو ﴿ٱلسَّمَآءِ﴾ و﴿مَآءًۭ﴾، وحكمه الوجوب عند القراء ولذلك سُمي «المد الواجب»، ويُمدّ أربع أو خمس حركات في رواية حفص", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1881", section: "التجويد", category: "الأحكام", level: "صعب", question: "ما القلقلة في التجويد؟", answer: "اضطراب الصوت عند النطق بالحرف ساكناً حتى تُسمع له نبرة قوية، وحروفها خمسة مجموعة في «قُطْبُ جَدٍّ»: القاف والطاء والباء والجيم والدال. وتكون صغرى إذا سكن الحرف في وسط الكلمة، وكبرى إذا وقع الوقف عليه في آخرها", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1882", section: "التجويد", category: "الأحكام", level: "متوسط", question: "ما الغنة؟", answer: "صوت رنّان يخرج من الخيشوم لا عمل للسان فيه، وهي صفة لازمة للنون والميم في جميع أحوالهما؛ وتُكمَل مقدار حركتين في مواضعها: النون والميم المشدَّدتين، والإدغام بغنة، والإخفاء", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1883", section: "التجويد", category: "الأحكام", level: "سهل", question: "ما حكم قراءة القرآن بالتجويد؟", answer: "تعلُّمه وتعليمه فرض كفاية على الأمة. وأمّا تطبيقه فيُفرَّق فيه: ما يختلّ به المعنى أو تتغير به بنية الكلمة — وهو اللحن الجليّ كإبدال حرف بحرف أو تغيير حركة الإعراب — فلا يجوز باتفاق؛ وأمّا اللحن الخفيّ المتعلق بكمال الأداء كمقادير المدود وإتمام الغنّة فمحل خلاف بين أهل العلم: منهم من ألحقه بالواجب أخذًا بقول ابن الجزري «والأخذ بالتجويد حتمٌ لازم»، ومنهم من عدّه من كمال الأداء المستحبّ لا الواجب", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1884", section: "التجويد", category: "الأحكام", level: "متوسط", question: "ما أنواع المد في التجويد؟", answer: "قسمان: المد الطبيعي (الأصلي) وهو ما لا يقوم حرف المد إلا به ولا سبب بعده، ومقداره حركتان؛ والمد الفرعي وهو ما زاد على الطبيعي لسبب، والسبب إمّا همز (المتصل والمنفصل والبدل) وإمّا سكون (العارض للسكون واللازم بأنواعه)", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1885", section: "التجويد", category: "الأحكام", level: "صعب", question: "متى يكون الإدغام بغير غنة؟", answer: "إذا وقعت اللام أو الراء بعد نون ساكنة أو تنوين، فتُدغم فيهما بغير غنة، نحو ﴿مِّن لَّدُنْهُ﴾ و﴿مِّن رَّبِّهِمْ﴾. وأمّا حروف «ينمو» — الياء والنون والميم والواو — فالإدغام فيها بغنة", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1886", section: "التجويد", category: "الأحكام", level: "متوسط", question: "ما التفخيم والترقيق؟", answer: "التفخيم تسمين الحرف حتى يمتلئ الفم بصداه، والترقيق تنحيفه. فحروف الاستعلاء السبعة المجموعة في «خُصَّ ضَغْطٍ قِظْ» مفخَّمة دائماً، وسائر الحروف مرقَّقة، وتتردد بين الحالين الراء ولام لفظ الجلالة والألف تبعاً لما قبلها؛ فتُفخَّم الراء إذا كانت مفتوحة أو مضمومة أو ساكنة بعد فتح أو ضم، وتُرقَّق إذا كانت مكسورة أو ساكنة بعد كسر أصلي", explanation: "يُستفاد منه في باب الأحكام. يُستفاد منه في باب الأحكام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1887", section: "التجويد", category: "أحكام النون الساكنة والتنوين", level: "سهل", question: "ما حكم النون الساكنة إذا جاء بعدها حرف من حروف الإخفاء؟", answer: "الإخفاء الحقيقي، وهو النطق بالنون الساكنة أو التنوين بصفةٍ بين الإظهار والإدغام، عاريًا عن التشديد، مع بقاء الغنة مقدار حركتين. وحروفه خمسة عشر، وهي الباقية بعد حروف الإظهار الستة وحروف الإدغام الستة وحرف الإقلاب (الباء)، ويقع في كلمة وفي كلمتين، نحو ﴿أَنفُسَهُمْ﴾ و﴿مِن قَبْلُ﴾", explanation: "يُستفاد منه في باب أحكام النون الساكنة والتنوين. يُستفاد منه في باب أحكام النون الساكنة والتنوين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1888", section: "التجويد", category: "أحكام النون الساكنة والتنوين", level: "سهل", question: "ما حروف الإدغام بغنة للنون الساكنة والتنوين؟", answer: "أربعة مجموعة في «ينمو»: الياء والنون والميم والواو. وشرطه أن يكون الحرف في كلمة أخرى، فإن اجتمع مع النون في كلمة واحدة وجب «الإظهار المطلق»، ولم يقع ذلك في القرآن إلا في أربع كلمات: ﴿ٱلدُّنْيَا﴾ و﴿بُنْيَٰنٌۭ﴾ و﴿قِنْوَانٌۭ﴾ و﴿صِنْوَانٌۭ﴾. والإدغام في النون والميم كامل، وفي الياء والواو ناقص تبقى معه صفة الغنة دون ذات الحرف", explanation: "يُستفاد منه في باب أحكام النون الساكنة والتنوين. يُستفاد منه في باب أحكام النون الساكنة والتنوين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1889", section: "التجويد", category: "أحكام النون الساكنة والتنوين", level: "سهل", question: "ما حروف الإظهار الحلقي؟", answer: "ستة حروف حلقية مجموعة في «أخي هاكَ علمًا حازه غيرُ خاسر»: الهمزة والهاء من أقصى الحلق، والعين والحاء من وسطه، والغين والخاء من أدناه. والإظهار: إخراج كل حرف من مخرجه من غير غنّة كاملة في الحرف المُظهَر، وسُمّي حلقيًّا لأن حروفه من الحلق؛ ومراتبه ثلاث تتفاوت بحسب قرب المخرج من مخرج النون: عليا مع الهمزة والهاء، ووسطى مع العين والحاء، ودنيا مع الغين والخاء", explanation: "يُستفاد منه في باب أحكام النون الساكنة والتنوين. يُستفاد منه في باب أحكام النون الساكنة والتنوين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1890", section: "التجويد", category: "أحكام الميم الساكنة", level: "سهل", question: "ما حكم الميم الساكنة إذا جاء بعدها حرف الباء؟", answer: "الإخفاء الشفوي، وهو النطق بالميم مخفاةً عند الباء مع بقاء الغنة مقدار حركتين من غير كزٍّ على الشفتين، نحو ﴿تَرْمِيهِم بِحِجَارَةٍۢ﴾؛ وهو مذهب جمهور أهل الأداء، وذهب بعضهم إلى إظهارها. وأحكام الميم الساكنة ثلاثة: الإخفاء الشفوي عند الباء، وإدغام المِثلين الصغير عند الميم، والإظهار الشفوي عند بقية الحروف، ويتأكّد بيانه عند الواو والفاء لاتحاد المخرج أو قربه", explanation: "يُستفاد منه في باب أحكام الميم الساكنة. يُستفاد منه في باب أحكام الميم الساكنة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1891", section: "التجويد", category: "المدود", level: "سهل", question: "ما المد الطبيعي ومقداره؟", answer: "المد الطبيعي (ويُسمى الأصلي): ما لا تقوم ذات حرف المد إلا به، ولا يتوقف على سببٍ من همزٍ أو سكون، ومقداره حركتان. وحروفه ثلاثة مجموعة في ﴿نُوحِيهَآ﴾: الألف الساكنة المفتوح ما قبلها، والواو الساكنة المضموم ما قبلها، والياء الساكنة المكسور ما قبلها", explanation: "يُستفاد منه في باب المدود. يُستفاد منه في باب المدود مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1892", section: "التجويد", category: "القلقلة", level: "سهل", question: "ما القلقلة وما حروفها؟", answer: "اضطراب المخرج عند النطق بالحرف ساكنًا حتى تُسمع له نبرة قوية، وحروفها خمسة مجموعة في «قُطْبُ جَدٍّ»: القاف والطاء والباء والجيم والدال. وتكون صغرى إذا سكن الحرف في وسط الكلمة، وكبرى إذا وقع الوقف عليه في آخرها", explanation: "يُستفاد منه في باب القلقلة. يُستفاد منه في باب القلقلة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1893", section: "التجويد", category: "الغنة", level: "سهل", question: "ما الغنة وأين مخرجها؟", answer: "صوت رنّان يخرج من الخيشوم لا عمل للسان فيه، وهي صفة لازمة للنون والميم في جميع أحوالهما فلا تنفكّان عنها؛ وليست مقدَّرة بحركتين على الإطلاق، وإنما تُكمَل مقدار حركتين في مواضعها: النون والميم المشدَّدتين، والإدغام بغنة، والإخفاء الحقيقي والشفوي، والإقلاب", explanation: "يُستفاد منه في باب الغنة. يُستفاد منه في باب الغنة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1894", section: "التجويد", category: "المدود", level: "متوسط", question: "ما مقدار المد المتصل الواجب؟", answer: "أربع أو خمس حركات في رواية حفص، وتجوز فيه ست حركات عند الوقف على همزٍ متطرِّف نحو ﴿ٱلسَّمَآءِ﴾ — فليست «الست» قولًا مطلقًا. ووجوبه وجوبٌ صناعيّ اصطلاحيّ عند القرّاء، بمعنى اتفاقهم على مدّه زيادةً على الطبيعي، لا وجوبٌ شرعيّ يأثم تاركه، ولهذا سُمّي «المد الواجب»", explanation: "يُستفاد منه في باب المدود. يُستفاد منه في باب المدود مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1895", section: "التجويد", category: "صفات الحروف", level: "متوسط", question: "ما صفة الاستعلاء وما حروفها؟", answer: "ارتفاع أقصى اللسان إلى الحنك الأعلى عند النطق بالحرف، وحروفها سبعة مجموعة في «خُصَّ ضَغْطٍ قِظْ»: الخاء والصاد والضاد والغين والطاء والقاف والظاء، وكلها مفخَّمة. وأربعة منها مطبقة (الصاد والضاد والطاء والظاء) فهي أقوى تفخيمًا لانضمام الإطباق إلى الاستعلاء، وثلاثة منفتحة (الخاء والغين والقاف)", explanation: "يُستفاد منه في باب صفات الحروف. يُستفاد منه في باب صفات الحروف مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1896", section: "التجويد", category: "أحكام النون الساكنة والتنوين", level: "سهل", question: "كم عدد أحكام النون الساكنة والتنوين؟", answer: "أربعة: الإظهار الحلقي، والإدغام (بغنة في «ينمو» وبغير غنة في اللام والراء)، والإقلاب عند الباء، والإخفاء الحقيقي في الخمسة عشر الباقية. والنون الساكنة نونٌ خالية من الحركة ثابتة لفظًا وخطًّا ووصلًا ووقفًا، تقع في الاسم والفعل والحرف وفي وسط الكلمة وطرفها؛ والتنوين نونٌ ساكنة زائدة تلحق آخر الاسم لفظًا ووصلًا لا خطًّا ولا وقفًا", explanation: "يُستفاد منه في باب أحكام النون الساكنة والتنوين. يُستفاد منه في باب أحكام النون الساكنة والتنوين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1897", section: "التجويد", category: "أحكام النون الساكنة والتنوين", level: "سهل", question: "عند أي حرف تُقلب النون الساكنة والتنوين ميمًا؟", answer: "عند الباء وحدها، وهذا هو «الإقلاب»: قلب النون الساكنة أو التنوين ميمًا خالصة، مع إخفاء هذه الميم عند الباء وبقاء الغنة مقدار حركتين — فليس قلبًا محضًا، إذ لو أُظهرت الميم لخرج عن حدّ الإقلاب. ومثاله في كلمة ﴿أَنۢبِئْهُم﴾، وفي كلمتين ﴿سَمِيعٌۢ بَصِيرٌۭ﴾", explanation: "يُستفاد منه في باب أحكام النون الساكنة والتنوين. يُستفاد منه في باب أحكام النون الساكنة والتنوين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1898", section: "التجويد", category: "أحكام النون الساكنة والتنوين", level: "متوسط", question: "ما الفرق بين الإدغام بغنة والإدغام بلا غنة؟", answer: "الإدغام بغنة في حروف «ينمو» وتبقى معه الغنة مقدار حركتين، وهو في النون والميم كامل (تذهب ذات الحرف وصفته)، وفي الياء والواو ناقص (تذهب ذات الحرف وتبقى صفة الغنة). والإدغام بغير غنة في اللام والراء وهو كامل لا تبقى معه غنة. وكلاهما مشروط بأن يكون الحرف في كلمة أخرى، وإلا وجب الإظهار المطلق", explanation: "يُستفاد منه في باب أحكام النون الساكنة والتنوين. يُستفاد منه في باب أحكام النون الساكنة والتنوين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1899", section: "الآداب والأخلاق", category: "الأخلاق العامة", level: "سهل", question: "بأيّ شيء وصف النبي ﷺ التبسّم في وجه المسلم؟", answer: "وصفه بأنه صدقة، قال ﷺ: «تبسُّمك في وجه أخيك لك صدقة». وهو جزء من حديث أطول عدّد فيه أبواب الصدقة: «...وأمرك بالمعروف ونهيك عن المنكر صدقة، وإرشادك الرجل في أرض الضلال لك صدقة، وإماطتك الحجر والشوكة والعظم عن الطريق لك صدقة، وإفراغك من دلوك في دلو أخيك لك صدقة». رواه الترمذي عن أبي ذر الغفاري رضي الله عنه", explanation: "يُستفاد منه في باب الأخلاق العامة. يُستفاد منه في باب الأخلاق العامة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1900", section: "الآداب والأخلاق", category: "الأخلاق العامة", level: "متوسط", question: "ما الغيبة في الإسلام؟", answer: "هي ذكرك أخاك بما يكره وهو غائب، ولا تكون غيبةً إلا إذا كان ما قيل فيه حقاً؛ فإن كان باطلاً فهو البهتان وهو أشدّ. قال ﷺ: «أتدرون ما الغيبة؟ قالوا: الله ورسوله أعلم. قال: ذكرك أخاك بما يكره. قيل: أفرأيت إن كان في أخي ما أقول؟ قال: إن كان فيه ما تقول فقد اغتبته، وإن لم يكن فيه فقد بهتَّه». رواه مسلم", explanation: "يُستفاد منه في باب الأخلاق العامة. يُستفاد منه في باب الأخلاق العامة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1901", section: "الآداب والأخلاق", category: "بر الوالدين", level: "سهل", question: "ما الحكم الشرعي لبر الوالدين؟", answer: "واجب وهو من أعظم القربات إلى الله، قال تعالى: ﴿وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا﴾ [الإسراء: 23]. وضدّه — العقوق — من أكبر الكبائر، قال ﷺ: «ألا أنبئكم بأكبر الكبائر؟ الإشراك بالله، وعقوق الوالدين، وشهادة الزور» متفق عليه", explanation: "يُستفاد منه في باب بر الوالدين. يُستفاد منه في باب بر الوالدين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1902", section: "الآداب والأخلاق", category: "بر الوالدين", level: "متوسط", question: "من قرن الله الإحسانَ إليهما بعبادته، وشكرَهما بشكره في القرآن؟", answer: "الوالدان؛ قرن الإحسان إليهما بعبادته وحده في قوله: ﴿وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا﴾ [الإسراء: 23]، وقرن شكرهما بشكره في قوله: ﴿أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ﴾ [لقمان: 14]", explanation: "يُستفاد منه في باب بر الوالدين. يُستفاد منه في باب بر الوالدين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1903", section: "الآداب والأخلاق", category: "الصدق والأمانة", level: "سهل", question: "ما اللقب الذي كان يُطلق على النبي محمد قبل البعثة؟", answer: "الصادق الأمين — اللقب الذي كان يُطلق على النبي محمد ﷺ قبل البعثة في مكة.", explanation: "يُستفاد منه في باب الصدق والأمانة. يُستفاد منه في باب الصدق والأمانة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1904", section: "الآداب والأخلاق", category: "الصدق والأمانة", level: "متوسط", question: "ما علامات المنافق كما جاء في الحديث؟", answer: "قال ﷺ: «آية المنافق ثلاث: إذا حدَّث كذب، وإذا وعد أخلف، وإذا اؤتمن خان» متفق عليه. وجاء في رواية أخرى بلفظ: «أربع من كُنّ فيه كان منافقاً خالصاً: إذا حدّث كذب، وإذا عاهد غدر، وإذا وعد أخلف، وإذا خاصم فجر» متفق عليه", explanation: "يُستفاد منه في باب الصدق والأمانة. يُستفاد منه في باب الصدق والأمانة مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1905", section: "الآداب والأخلاق", category: "آداب الطعام", level: "سهل", question: "ما يُقال قبل الأكل، وماذا يصنع من نسي التسمية في أوله؟", answer: "يُسمّي الله؛ قال ﷺ لعمر بن أبي سلمة رضي الله عنهما: «يا غلامُ، سمِّ الله، وكُلْ بيمينك، وكُلْ ممّا يليك» (متفق عليه: البخاري ٥٣٧٦، مسلم ٢٠٢٢)، ويُجزئ في ذلك قول: «بسم الله». فمن نسي التسمية في أول طعامه قال إذا ذكر: «بسم الله أوّله وآخره» (رواه أبو داود والترمذي وحسّنه، وهو في حصن المسلم)", explanation: "يُستفاد منه في باب آداب الطعام. يُستفاد منه في باب آداب الطعام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1906", section: "الآداب والأخلاق", category: "آداب الطعام", level: "سهل", question: "ما يُقال بعد الطعام، وهل يتعيّن لفظ واحد؟", answer: "من أشهر ما ورد: «الحمد لله الذي أطعمنا وسقانا وجعلنا مسلمين» (رواه أبو داود والترمذي، وهو في حصن المسلم). وورد أيضًا: «الحمد لله الذي أطعمني هذا ورزقنيه من غير حولٍ منّي ولا قوّة»، وفي فضله: «غُفر له ما تقدّم من ذنبه» (رواه الترمذي وحسّنه). ولا يتعيّن لفظ بعينه؛ فأصل السنّة حمد الله على الطعام، وقد قال ﷺ: «إنّ الله ليرضى عن العبد أن يأكل الأكلة فيحمده عليها، أو يشرب الشربة فيحمده عليها» (رواه مسلم ٢٧٣٤)", explanation: "يُستفاد منه في باب آداب الطعام. يُستفاد منه في باب آداب الطعام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1907", section: "الآداب والأخلاق", category: "آداب الطعام", level: "متوسط", question: "ما آداب الأكل الثلاثة المجموعة في حديث واحد؟", answer: "جمعها النبي ﷺ في وصيته لعمر بن أبي سلمة رضي الله عنهما وقد كانت يده تطيش في الصحفة: «يا غلامُ، سمِّ الله، وكُلْ بيمينك، وكُلْ ممّا يليك» (متفق عليه: البخاري ٥٣٧٦، مسلم ٢٠٢٢). فهي: التسمية، والأكل باليمين — وقد نهى ﷺ عن الأكل بالشمال وقال: «فإنّ الشيطان يأكل بشماله» (رواه مسلم ٢٠٢٠) — والأكل ممّا يلي الآكل. وقيّد أهل العلم الأدب الثالث بالطعام الصنف الواحد، أمّا إذا اختلفت الأصناف فلا بأس بمدّ اليد إلى غير ما يليه", explanation: "يُستفاد منه في باب آداب الطعام. يُستفاد منه في باب آداب الطعام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1908", section: "الآداب والأخلاق", category: "آداب السلام", level: "سهل", question: "من يبدأ بالسلام، وما حكم ابتدائه وردّه؟", answer: "جاء ترتيبه في حديث أبي هريرة رضي الله عنه: «يُسلّم الصغير على الكبير، والمارّ على القاعد، والقليل على الكثير» (رواه البخاري ٦٢٣١)، وفي رواية الصحيحين: «يُسلّم الراكب على الماشي، والماشي على القاعد». وهذا ترتيب استحباب لا إلزام؛ وخيرهما الذي يبدأ بالسلام (رواه أبو داود). وابتداء السلام سنّة، وردّه واجب — فرض كفاية إذا كانوا جماعة، وعينٌ على المنفرد — قال تعالى: ﴿وَإِذَا حُيِّيتُم بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ رُدُّوهَا﴾ (النساء: ٨٦)", explanation: "يُستفاد منه في باب آداب السلام. يُستفاد منه في باب آداب السلام مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1909", section: "الآداب والأخلاق", category: "آداب المجلس", level: "سهل", question: "ما كفّارة المجلس، ومتى تُقال؟", answer: "«سبحانك اللهمّ وبحمدك، أشهد أن لا إله إلا أنت، أستغفرك وأتوب إليك»؛ قال ﷺ: «من جلس في مجلسٍ فكثُر فيه لَغَطُه، فقال قبل أن يقوم من مجلسه ذلك: سبحانك اللهمّ وبحمدك... إلا غُفر له ما كان في مجلسه ذلك» (رواه الترمذي وقال: حسن صحيح، وأبو داود، وهو في حصن المسلم). فمحلّها عند القيام من المجلس، وهي كفّارة لما يقع فيه من اللغط واللغو", explanation: "يُستفاد منه في باب آداب المجلس. يُستفاد منه في باب آداب المجلس مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1910", section: "الآداب والأخلاق", category: "بر الوالدين", level: "سهل", question: "أيّ الكبائر قرنها النبي ﷺ بالشرك بالله في حديث أكبر الكبائر؟", answer: "عقوق الوالدين؛ ففي حديث أبي بكرة رضي الله عنه قال ﷺ: «ألا أُنبّئكم بأكبر الكبائر؟ — ثلاثًا — قلنا: بلى يا رسول الله. قال: الإشراك بالله، وعقوق الوالدين» (متفق عليه: البخاري ٢٦٥٤، مسلم ٨٧). ونظير هذا الاقتران في القرآن: ﴿وَقَضَىٰ رَبُّكَ أَلَّا تَعْبُدُوا إِلَّا إِيَّاهُ وَبِالْوَالِدَيْنِ إِحْسَانًا﴾ (الإسراء: ٢٣)", explanation: "يُستفاد منه في باب بر الوالدين. يُستفاد منه في باب بر الوالدين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1911", section: "الآداب والأخلاق", category: "بر الوالدين", level: "متوسط", question: "ما ضابط عقوق الوالدين، وهل تجب طاعتهما في كل شيء؟", answer: "ضبطه أهل العلم بأنّه: كلّ ما يتأذّى به الوالدان من قول أو فعل ممّا ليس بواجبٍ شرعيّ على الولد تركُه، أو تركُ ما يلزمه من برّهما مع القدرة وانتفاء العذر. وأدنى ما نُهي عنه التأفّف: ﴿فَلَا تَقُل لَّهُمَا أُفٍّ وَلَا تَنْهَرْهُمَا وَقُل لَّهُمَا قَوْلًا كَرِيمًا﴾ (الإسراء: ٢٣)، فما فوقه أشدّ. وطاعتهما واجبة في المعروف لا في معصية الله، ومع ذلك تبقى الصحبة بالإحسان: ﴿وَإِن جَاهَدَاكَ عَلَىٰ أَن تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا ۖ وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا﴾ (لقمان: ١٥)", explanation: "يُستفاد منه في باب بر الوالدين. يُستفاد منه في باب بر الوالدين مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1912", section: "الآداب والأخلاق", category: "صلة الرحم", level: "سهل", question: "ما الوارد في جزاء صلة الرحم، وكيف فهم العلماء «الزيادة في العمر»؟", answer: "قال ﷺ: «من أحبّ أن يُبسَط له في رزقه، ويُنسَأ له في أثره، فليَصِلْ رحمه» (متفق عليه: البخاري ٥٩٨٦، مسلم ٢٥٥٧). ومعنى «يُنسَأ له في أثره»: يُؤخَّر له في أجله. وللعلماء في توجيهها وجهان مشهوران: أنّ المراد البركة في العمر والتوفيق لعمارته بالطاعة، أو أنّ الزيادة والنقص في علم الملك المُوكَّل وفيما في صحف الملائكة، وأمّا ما في علم الله فلا يتغيّر ولا يتبدّل", explanation: "يُستفاد منه في باب صلة الرحم. يُستفاد منه في باب صلة الرحم مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1913", section: "الآداب والأخلاق", category: "الجوار", level: "متوسط", question: "بمَ عبّر النبي ﷺ عن عِظَم حقّ الجار؟", answer: "بتكرار وصية جبريل به حتى ظنّ ﷺ أنّه سيجعل له نصيبًا من الميراث؛ قال: «ما زال جبريل يوصيني بالجار حتى ظننتُ أنّه سَيُوَرِّثُه» (متفق عليه: البخاري ٦٠١٤، مسلم ٢٦٢٤) — والظنّ هنا منه ﷺ لا من الصحابة. وقرن الإيمانَ بحقّه فقال: «من كان يؤمن بالله واليوم الآخر فليُكرم جاره» (متفق عليه)، وقال: «والله لا يؤمن — ثلاثًا — قيل: ومن يا رسول الله؟ قال: الذي لا يأمن جارُه بوائقه» (رواه البخاري ٦٠١٦)", explanation: "يُستفاد منه في باب الجوار. يُستفاد منه في باب الجوار مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" },
  { id: "1914", section: "الآداب والأخلاق", category: "أخلاق المسلم", level: "سهل", question: "ما فضل الرفق كما جاء في حديث عائشة رضي الله عنها؟", answer: "قال ﷺ: «إنّ الرفق لا يكون في شيء إلا زانه، ولا يُنزع من شيء إلا شانه» (رواه مسلم ٢٥٩٤). وفي الباب نفسه: «إنّ الله رفيقٌ يحبّ الرفق، ويُعطي على الرفق ما لا يُعطي على العُنف، وما لا يُعطي على ما سواه» (رواه مسلم ٢٥٩٣)، وقال: «من يُحرَم الرفق يُحرَم الخير كلّه» (رواه مسلم ٢٥٩٢)", explanation: "يُستفاد منه في باب أخلاق المسلم. يُستفاد منه في باب أخلاق المسلم مع الرجوع إلى مراجع مجالس العلم.", reference: "مراجع مجالس العلم" }
];

